/**
 * Приведение запроса виджета к общему конверту.
 *
 * Конверт тот же, что у VK-адаптера (builds/vk-adapter/normalize-vk.js):
 * channel, user_id, session_key, text, ts. Это не лишняя работа — благодаря
 * одинаковому конверту один и тот же агент обслужит и сайт, и VK, и Авито,
 * а добавление канала станет новым адаптером, а не переписыванием сборки.
 *
 * У веб-канала нет user_id, поэтому session_id играет обе роли. Он приходит
 * из браузера, то есть управляем снаружи — значит всё, что на нём завязано,
 * должно быть безвредно при подделке. Чужая память — это чужой разговор об
 * остеклении, не более; лимит считается по тому же ключу, поэтому подделка
 * не даёт обхода, а лишь делит чужую квоту.
 */
'use strict';

const MAX_TEXT = 2000; // человек столько не пишет; отсекаем вставленную простыню
const MAX_NAME = 120;
const MAX_PHONE = 32;
const MAX_ADDRESS = 300; // адрес объекта — необязательное поле формы контактов

/**
 * Выбрасывает управляющие символы и обрезает по длине.
 *
 * Посимвольно, а не регуляркой с диапазоном: диапазон управляющих символов
 * приходится записывать escape-последовательностями, которые невидимы при
 * ревью и легко ломаются при копировании. Здесь условие видно глазами.
 */
function clean(value, max) {
  if (value == null) return '';
  const s = String(value);
  let out = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code < 32 || code === 127) continue;
    out += s[i];
  }
  return out.trim().slice(0, max);
}

/** Телефон нужен менеджеру, а не парсеру: храним как есть, сверяем только длину. */
function phoneDigits(raw) {
  return clean(raw, MAX_PHONE).replace(/\D/g, '').length;
}

function normalizeWebRequest(body) {
  const b = body && typeof body === 'object' ? body : {};
  const sessionId = clean(b.session_id, 64);
  const contact = b.contact && typeof b.contact === 'object' ? b.contact : null;

  const envelope = {
    channel: 'web',
    session_id: sessionId,
    user_id: sessionId,
    session_key: sessionId ? 'web:' + sessionId : '',
    text: clean(b.message, MAX_TEXT),
    ts: new Date().toISOString(),
    is_contact: false,
    contact_name: '',
    contact_phone: '',
    contact_address: '',
    contact_consent: false,
    valid: false,
    invalid_reason: '',
  };

  if (!sessionId) {
    envelope.invalid_reason = 'нет session_id';
    return envelope;
  }

  if (contact) {
    envelope.is_contact = true;
    envelope.contact_name = clean(contact.name, MAX_NAME);
    envelope.contact_phone = clean(contact.phone, MAX_PHONE);
    // Схлопываем повторные пробелы: адрес уходит в DaData и в строку лида,
    // а «Самара,  Ново-Садовая» — это лишний шум и в запросе, и в отчёте.
    envelope.contact_address = clean(contact.address, MAX_ADDRESS).replace(/\s+/g, ' ');
    envelope.contact_consent = contact.consent === true;

    // 152-ФЗ. Галочка проверяется и в виджете, и здесь. Клиентскую проверку
    // обойдёт любой, кто открыл консоль; серверную — нет. Телефон без согласия
    // не сохраняется, и это не обсуждается.
    if (!envelope.contact_consent) {
      envelope.invalid_reason = 'нет согласия на обработку персональных данных';
      return envelope;
    }
    if (phoneDigits(envelope.contact_phone) < 10) {
      envelope.invalid_reason = 'телефон короче 10 цифр';
      return envelope;
    }
    envelope.valid = true;
    return envelope;
  }

  if (!envelope.text) {
    envelope.invalid_reason = 'пустое сообщение';
    return envelope;
  }

  envelope.valid = true;
  return envelope;
}

// ---------------------------------------------------------------------------
// Склейка с n8n. Всё выше внедряется из normalize-web.js генератором
// make-workflow.py. Не править здесь — править источник и перегенерировать.
// ---------------------------------------------------------------------------
return $input.all().map((item) => ({
  json: normalizeWebRequest(item.json.body !== undefined ? item.json.body : item.json),
}));

/**
 * Разбор ответа Redis INCR и решение по лимиту запросов.
 *
 * Виджет стоит на чужом сайте и открыт всему интернету. Без лимита один
 * человек с консолью браузера за ночь выставляет клиенту счёт за Yandex AI
 * Studio. Поэтому лимит — часть сборки, а не опция.
 *
 * Почему не читаем ответ Redis напрямую: узел Redis в n8n кладёт результат
 * INCR под именем ключа, а ключ у нас собирается выражением. Полагаться на
 * форму ответа — значит однажды получить `undefined > 20 === false` и молча
 * остаться без защиты, ничего при этом не заметив. Берём первое числовое
 * значение, какой бы ни была обёртка.
 */
'use strict';

const WINDOW_SECONDS = 600; // 10 минут — обязано совпадать с TTL в узле Redis
const MAX_MESSAGES = 20;

function readCount(redisJson) {
  if (redisJson == null) return null;
  if (typeof redisJson === 'number') return Number.isFinite(redisJson) ? redisJson : null;
  if (typeof redisJson === 'string') return /^\d+$/.test(redisJson.trim()) ? Number(redisJson.trim()) : null;
  if (typeof redisJson !== 'object') return null;
  for (const v of Object.values(redisJson)) {
    if (typeof v === 'number' && Number.isFinite(v)) return v;
    if (typeof v === 'string' && /^\d+$/.test(v.trim())) return Number(v.trim());
  }
  return null;
}

/**
 * Если Redis недоступен или ответил непонятно — пропускаем запрос.
 *
 * Это осознанный выбор в пользу доступности. Отказать всем посетителям сайта
 * из-за сбоя вспомогательного сервиса дороже, чем на несколько минут остаться
 * без лимита: первое стоит клиенту всех лидов, второе — нескольких рублей.
 * Но факт помечается флагом, чтобы в логе исполнения было видно, что защита
 * не сработала, а не казалось, что всё в порядке.
 */
function decide(count) {
  if (count == null) {
    return { rate_count: null, rate_limited: false, rate_degraded: true };
  }
  return { rate_count: count, rate_limited: count > MAX_MESSAGES, rate_degraded: false };
}

function limitReply() {
  return 'Слишком много сообщений подряд — сделайте паузу на пару минут.\n\n' +
    'Если вопрос срочный, позвоните напрямую: так быстрее.';
}

// ---------------------------------------------------------------------------
//   источник: builds/02-lead-widget/rate-limit.js
//
// Узел Redis подменяет элемент своим ответом, поэтому конверт берём обратно из
// узла нормализации, а не из $json — иначе session_id потеряется ровно здесь.
// ---------------------------------------------------------------------------
const envelope = $('Normalize Web Request').first().json;

return $input.all().map((item) => {
  const verdict = decide(readCount(item.json));
  return {
    json: {
      ...envelope,
      ...verdict,
      reply: verdict.rate_limited ? limitReply() : '',
    },
  };
});

/**
 * Решение: показывать ли форму контактов.
 *
 * ЭТО САМОЕ ВАЖНОЕ ПРАВИЛО СБОРКИ, И ОНО НАМЕРЕННО НЕ В ПРОМПТЕ.
 *
 * Форма появляется тогда и только тогда, когда подworkflow расчёта поставил в
 * Redis ключ `quoted:<session_id>`. То есть — когда человеку действительно
 * показали цену.
 *
 * Промпт можно уговорить: «покажи форму», «мне срочно», достаточно длинный
 * разговор — и модель уступит. Ключ в Redis уговорить нельзя: его ставит код
 * после успешного расчёта, и он либо есть, либо нет. Разница между «модели
 * велено не просить телефон раньше времени» и «телефон физически невозможно
 * попросить раньше времени» — это разница между обещанием и гарантией.
 *
 * Зачем вообще: посетитель, у которого просят телефон до того, как дали
 * пользу, закрывает чат. Весь виджет построен вокруг обратного порядка, и эта
 * функция — то место, где порядок держится.
 */
'use strict';

/**
 * Redis-узел n8n кладёт результат GET под именем свойства, а не под именем
 * ключа, и при отсутствии ключа отдаёт null, undefined или пустую строку —
 * в зависимости от версии и настроек. Считаем меткой только явное значение.
 */
function wasQuoted(redisJson, propertyName) {
  if (redisJson == null || typeof redisJson !== 'object') return false;

  const direct = redisJson[propertyName];
  if (direct !== undefined) {
    return direct !== null && String(direct).trim() !== '';
  }

  // Имя свойства могло разойтись с настройкой узла — тогда ищем любое
  // непустое значение. Лучше показать форму на один ход позже, чем не
  // показать никогда из-за переименованного поля.
  for (const v of Object.values(redisJson)) {
    if (v !== null && v !== undefined && String(v).trim() !== '') return true;
  }
  return false;
}

/**
 * @param {object} opts
 * @param {boolean} opts.quoted        поставлена ли метка расчёта
 * @param {boolean} opts.isContact     это уже отправка контактов
 * @param {string}  opts.agentReply    что ответил агент
 * @param {string}  opts.fallbackReply что сказать, если агент промолчал
 */
function decideForm(opts) {
  const o = opts || {};
  const reply = String(o.agentReply == null ? '' : o.agentReply).trim();

  return {
    reply: reply || String(o.fallbackReply || ''),
    // Форму не показываем в ответ на саму отправку контактов: человек их уже
    // прислал, и повторная форма выглядит так, будто заявка не ушла.
    form: o.quoted === true && o.isContact !== true ? 'contact' : '',
    agent_silent: reply === '',
  };
}

// ---------------------------------------------------------------------------
//   источник: builds/02-lead-widget/form-gate.js
//
// Узлы Redis и Agent оба подменяют элемент своим выводом, поэтому и конверт,
// и ответ агента берём по именам узлов, а не из $json.
// ---------------------------------------------------------------------------
const envelope = $('Normalize Web Request').first().json;
const agent = $('Lead Agent').first().json;
const FALLBACK = "Секунду, соединяюсь с менеджером — а пока можно позвонить напрямую: **+7 (846) 000-00-00**";

return $input.all().map((item) => {
  const decided = decideForm({
    quoted: wasQuoted(item.json, 'quoted'),
    isContact: envelope.is_contact === true,
    agentReply: agent.output,
    fallbackReply: FALLBACK,
  });
  return { json: { ...envelope, ...decided } };
});

/**
 * Разбор ответа DaData «стандартизация адресов» в решение: считать или переспросить.
 *
 * Правило простое и на нём держится доверие к сборке: НЕТ ВНЯТНОГО АДРЕСА —
 * НЕТ ЦЕНЫ. Тест 3 из брифа именно про это: на «ул. Пушкина» бот обязан
 * переспросить, а не назвать сумму. Цена, названная по адресу, которого не
 * существует, — это счёт, который заказчик потом не выставит, и разговор,
 * который он проведёт с нами, а не с клиентом.
 *
 * Адрес НЕ влияет на стоимость. Районных прайсов у нас нет, и наценку по
 * району мы не изобретаем (см. PRICING-SOURCES.md). Адрес нужен, чтобы
 * (1) убедиться, что объект реальный, (2) убедиться, что он в зоне выезда,
 * (3) передать его замерщику в разобранном виде.
 *
 * Почему разбираем коды, а не смотрим на координаты: DaData отдаёт готовый
 * вердикт полями qc и qc_complete. Выводить то же самое из координат — писать
 * эвристику поверх сервиса, который уже ответил.
 */
'use strict';

/** Регионы, куда компания выезжает. Меняется при внедрении у заказчика. */
const SERVICE_REGIONS = ['самарская'];

/**
 * qc — нужна ли ручная проверка распознанного адреса.
 * Значения из документации DaData, не выдуманы.
 */
const QC = {
  CONFIDENT: 0, // распознан уверенно
  NEEDS_CHECK: 1, // лишние части или данных мало
  GARBAGE: 2, // пустой или заведомо мусорный
  AMBIGUOUS: 3, // есть альтернативные варианты
};

/**
 * qc_complete — годится ли адрес для доставки. Нам он говорит, чего не хватает.
 * Порядок в этой таблице — это порядок, в котором мы просим уточнить: нет
 * смысла спрашивать номер дома, если не назван город.
 */
const INCOMPLETE_REASON = {
  1: 'не указан регион',
  2: 'не указан город',
  3: 'не указана улица',
  4: 'не указан номер дома',
  6: 'адрес неполный',
  7: 'это адрес не в России',
};

function str(v) {
  return v == null ? '' : String(v).trim();
}

function firstRecord(response) {
  // DaData отвечает массивом даже на один адрес. Узел HTTP Request в n8n
  // отдаёт его то массивом, то объектом с полем data — принимаем оба.
  if (Array.isArray(response)) return response[0] || null;
  if (response && typeof response === 'object') {
    if (Array.isArray(response.data)) return response.data[0] || null;
    if (response.result !== undefined || response.qc !== undefined) return response;
  }
  return null;
}

function inServiceArea(region) {
  const r = str(region).toLowerCase().replace(/ё/g, 'е');
  if (!r) return false;
  return SERVICE_REGIONS.some((s) => r.includes(s));
}

/**
 * @returns {{ok: boolean, reason: string, ask: string, address: object}}
 *   ok      — можно ли считать смету
 *   reason  — техническая причина отказа, для лога
 *   ask     — что сказать человеку; пусто, если всё в порядке
 *   address — разобранный адрес для лида
 */
function interpretAddress(response) {
  const rec = firstRecord(response);

  if (!rec) {
    // Сервис не ответил или ответил непонятно. Это НЕ повод отказать человеку:
    // адрес на цену не влияет, а терять лид из-за сбоя стороннего сервиса —
    // худший из возможных исходов. Считаем, но помечаем адрес непроверенным.
    return {
      ok: true,
      degraded: true,
      reason: 'DaData не ответила — адрес не проверен',
      ask: '',
      address: { raw: '', result: '', city: '', street: '', house: '', region: '' },
    };
  }

  const address = {
    raw: str(rec.source),
    result: str(rec.result),
    region: str(rec.region_with_type) || str(rec.region),
    city: str(rec.city_with_type) || str(rec.city) || str(rec.settlement_with_type),
    district: str(rec.city_district_with_type),
    street: str(rec.street_with_type),
    house: str(rec.house),
    lat: str(rec.geo_lat),
    lon: str(rec.geo_lon),
    fias_level: rec.fias_level == null ? '' : String(rec.fias_level),
  };

  const qc = Number(rec.qc);
  const complete = Number(rec.qc_complete);

  if (qc === QC.GARBAGE) {
    return {
      ok: false,
      degraded: false,
      reason: 'qc=2: адрес пустой или мусорный',
      ask: 'Не разобрал адрес. Напишите, пожалуйста, город, улицу и номер дома.',
      address,
    };
  }

  // Иностранный адрес ловим раньше зоны выезда: человеку полезнее услышать
  // «мы работаем только в Самарской области», чем «не указан регион».
  if (complete === 7) {
    return {
      ok: false,
      degraded: false,
      reason: 'qc_complete=7: иностранный адрес',
      ask: 'Мы работаем в Самаре и Самарской области. Подскажите адрес объекта в этом регионе.',
      address,
    };
  }

  if (INCOMPLETE_REASON[complete]) {
    const what = INCOMPLETE_REASON[complete];
    return {
      ok: false,
      degraded: false,
      reason: `qc_complete=${complete}: ${what}`,
      ask: `Уточните, пожалуйста, адрес — ${what}.`,
      address,
    };
  }

  if (qc === QC.AMBIGUOUS) {
    return {
      ok: false,
      degraded: false,
      reason: 'qc=3: несколько подходящих адресов',
      ask: 'Таких адресов в городе несколько. Уточните, пожалуйста, район или полное название улицы.',
      address,
    };
  }

  // Регион определился, но не наш. Честно сказать сейчас дешевле, чем
  // отправить замерщика за 400 км и разбираться потом.
  if (address.region && !inServiceArea(address.region)) {
    return {
      ok: false,
      degraded: false,
      reason: `вне зоны выезда: ${address.region}`,
      ask: `Мы работаем в Самаре и Самарской области, а ${address.region} — за пределами выезда. Подсказать кого-то в вашем городе не смогу, но посчитать для объекта в Самарской области — с радостью.`,
      address,
    };
  }

  // qc=1 — данных маловато, но дом и город есть. Считаем, помечаем адрес
  // приблизительным: замерщик всё равно позвонит перед выездом.
  if (qc === QC.NEEDS_CHECK) {
    return {
      ok: true,
      degraded: true,
      reason: 'qc=1: адрес распознан неточно',
      ask: '',
      address,
    };
  }

  return { ok: true, degraded: false, reason: '', ask: '', address };
}
// ---------------------------------------------------------------------------
//   источник: builds/02-lead-widget/address.js
//
// Тот же разбор ответа DaData, что и в подworkflow расчёта, но на пути лида.
// Здесь вердикт НИКОГДА не отменяет запись: он только решает, ляжет ли строка
// на ручную проверку. Адрес на цену не влияет, а потерять уже отданный
// телефон из-за плохого адреса — самый дорогой возможный исход.
// ---------------------------------------------------------------------------
return $input.all().map((item) => ({ json: { lead_address: interpretAddress(item.json) } }));

/**
 * Сборка строки лида из того, что накопилось за разговор.
 *
 * Лид — это единственный результат, за который клиент платит. Всё остальное в
 * сборке существует ради того, чтобы эта строка появилась и была полезной
 * менеджеру. Поэтому здесь два правила, и оба жёстче обычного:
 *
 * 1. БЕЗ СОГЛАСИЯ СТРОКИ НЕТ. 152-ФЗ. Галочку проверяет виджет, но виджет
 *    живёт в браузере посетителя и обходится консолью за десять секунд.
 *    Проверка здесь — единственная, которая что-то гарантирует.
 *
 * 2. ЛИД НЕ ТЕРЯЕТСЯ НИКОГДА. Плохой адрес, недоступная DaData, пропавший
 *    расчёт — всё это поводы пометить строку на ручную проверку, но не поводы
 *    выбросить телефон человека, который его оставил. Правило CLAUDE.md:
 *    «сбой разбора уходит на ручную проверку, а не в автоматический отказ».
 */
'use strict';

const MAX = { name: 120, phone: 32, address: 300, reason: 500 };

function str(v, max) {
  if (v == null) return '';
  return String(v).trim().replace(/\s+/g, ' ').slice(0, max);
}

/**
 * Читает снимок расчёта из Redis.
 *
 * Ключ `quoted:<session_id>` раньше хранил строку «1» — только факт расчёта.
 * Теперь там JSON со сметой, но старые ключи живут ещё час после обновления,
 * и разбор обязан пережить оба формата. Возврат null означает «расчёта не
 * видно» — это повод для ручной проверки, а не для отказа.
 */
function parseQuoted(raw) {
  if (raw == null) return null;
  const s = typeof raw === 'string' ? raw.trim() : raw;
  if (s === '' || s === '1' || s === 1) return null;

  let o = s;
  if (typeof s === 'string') {
    try { o = JSON.parse(s); } catch (e) { return null; }
  }
  if (!o || typeof o !== 'object') return null;

  const low = Number(o.price_low);
  const high = Number(o.price_high);
  if (!Number.isFinite(low) || !Number.isFinite(high)) return null;

  return {
    price_low: low,
    price_high: high,
    configuration: str(o.configuration, 40),
    glazing: str(o.glazing, 20),
  };
}

/**
 * @param {object} opts
 * @param {object} opts.envelope   конверт из normalize-web.js
 * @param {object} opts.address    вердикт interpretAddress, или null если адреса нет
 * @param {object} opts.quoted     результат parseQuoted, или null
 * @returns {{ok: boolean, reason: string, row: object}}
 *   ok=false означает, что строку писать НЕЛЬЗЯ (нет согласия). Во всех
 *   остальных случаях строка пишется, но может быть помечена needs_review.
 */
function buildLead(opts) {
  const o = opts || {};
  const env = o.envelope && typeof o.envelope === 'object' ? o.envelope : {};
  const quoted = o.quoted || null;
  const addr = o.address || null;

  // Согласие. Единственная проверка во всей функции, которая отказывает.
  if (env.contact_consent !== true) {
    return { ok: false, reason: 'нет согласия на обработку персональных данных', row: null };
  }

  const phone = str(env.contact_phone, MAX.phone);
  if (phone.replace(/\D/g, '').length < 10) {
    return { ok: false, reason: 'телефон короче 10 цифр', row: null };
  }

  const review = [];
  if (!quoted) review.push('расчёт не найден — форма показалась без сметы');

  let addressRaw = '';
  let addressClean = '';
  let addressNote = '';
  if (addr) {
    addressRaw = str(addr.address && addr.address.raw, MAX.address);
    addressClean = str(addr.address && addr.address.result, MAX.address);
    addressNote = str(addr.reason, MAX.reason);
    if (addr.degraded) review.push('адрес не проверен — DaData недоступна');
    else if (!addr.ok) review.push('адрес не подтверждён: ' + addressNote);
  } else {
    addressNote = 'адрес не указан';
  }

  return {
    ok: true,
    reason: '',
    row: {
      session_id: str(env.session_id, 64),
      created_at: new Date().toISOString(),
      channel: str(env.channel, 16) || 'web',
      name: str(env.contact_name, MAX.name),
      phone,
      consent: true,
      address_raw: addressRaw,
      address_clean: addressClean,
      address_note: addressNote,
      price_low: quoted ? quoted.price_low : null,
      price_high: quoted ? quoted.price_high : null,
      configuration: quoted ? quoted.configuration : '',
      glazing: quoted ? quoted.glazing : '',
      needs_review: review.length > 0,
      review_reason: str(review.join('; '), MAX.reason),
    },
  };
}

/** Что сказать человеку после того, как строка записана. */
function leadReply(row, clientPhone) {
  const named = row && row.name ? row.name.split(' ')[0] : '';
  const hello = named ? named + ', заявка принята' : 'Заявка принята';
  const tail = clientPhone
    ? '\n\nЕсли удобнее позвонить самому: **' + clientPhone + '**'
    : '';
  return hello + '. Замерщик свяжется с вами, чтобы согласовать время — ' +
    'замер бесплатный и ни к чему не обязывает.' + tail;
}
// ---------------------------------------------------------------------------
//   источник: builds/02-lead-widget/lead.js
//
// Конверт и метку расчёта берём по именам узлов: и Redis, и HTTP подменяют
// элемент своим ответом, поэтому $json здесь — это не конверт.
//
// Вердикт по адресу может отсутствовать: поле адреса в форме необязательное,
// и при пустом адресе ветка DaData не выполняется вовсе. Обращение к узлу,
// который не выполнялся, бросает исключение — отсюда try/catch.
// ---------------------------------------------------------------------------
const envelope = $('Normalize Web Request').first().json;
const CLIENT_PHONE = "+7 (846) 000-00-00";

let quotedRaw = null;
try {
  const q = $('Check Quoted — Lead').first().json;
  quotedRaw = q && q.quoted !== undefined ? q.quoted : null;
} catch (e) {
  quotedRaw = null;
}

let addressVerdict = null;
if (envelope.contact_address) {
  try {
    addressVerdict = $('Check Lead Address').first().json.lead_address || null;
  } catch (e) {
    addressVerdict = null;
  }
}

const built = buildLead({
  envelope,
  address: addressVerdict,
  quoted: parseQuoted(quotedRaw),
});

return [{
  json: {
    session_id: envelope.session_id,
    lead_ok: built.ok,
    lead_reason: built.reason,
    ...(built.row || {}),
    reply: built.ok
      ? leadReply(built.row, CLIENT_PHONE)
      : 'Не получилось сохранить заявку: ' + built.reason +
        '. Позвоните, пожалуйста, напрямую: **' + CLIENT_PHONE + '**',
  },
}];
